const data = $input.first().json;

const issues = data.items ?? [];

return {data : issues.map(issue => ({
  json: {
    event: "opened",
    number: issue.number,
    title: issue.title,
    body: issue.body,
    state: issue.state,
    url: issue.html_url,
    author: issue.user?.login,
    tags: issue.labels.map(x => ({
      name: x.name
    }))
  }
}))};

const data = $input.first().json;

const issues = data.items ?? [];

return {data: issues.map(issue => ({
  json: {
    event: "closed",
    number: issue.number,
    title: issue.title,
    body: issue.body,
    state: issue.state,
    url: issue.html_url,
    author: issue.user?.login,
    tags: issue.labels.map(x => ({
      name: x.name
    }))
  }
}))};

const items = $input.all();

const dates = $('Previous Date').first().json;

const startDate = new Date(dates.previousDate);
const endDate = new Date(dates.currentDate);

const issues = items
  .filter(item => {
    const event = item.json;

    const eventDate = new Date(event.created_at);

    return (
      event.event === 'reopened' &&
      eventDate >= startDate &&
      eventDate <= endDate
    );
  })
  .map(item => {
    const issue = item.json.issue;

    return {
      event: "reopened",
      number: issue.number,
      title: issue.title,
      body: issue.body,
      state: issue.state,
      url: issue.html_url,
      author: issue.user?.login,
      date: item.json.created_at,
      tags: (issue.labels ?? []).map(x => ({
        name: x.name
      }))
    };
  });

return [
  {
    json: {
      data: issues
    }
  }
];

const items = $input.all();

const data = items.flatMap(item => item.json.data ?? []);

return [
  {
    json: {
      data
    }
  }
];

const items = $input.all();

const data = items.flatMap(item => item.json.data ?? []);

const previousDiff = items.find(item => item.json.diff !== undefined)?.json.diff ?? null;

return [
  {
    json: {
      data: data.map(item => item.json ?? item),
      previousDiff
    }
  }
];
